import re
import json
from typing import List, Dict, Any, Optional

# Helpers (assumed to be available in the sandbox)
# node_by_title(doc, title) -> node
# node_by_id(doc, node_id) -> node
# children(doc, node) -> list of child node dicts
# scope_nodes(doc, scope) -> list of child node dicts of the scope
# table_rows(node) -> list of (row_index, {column: value}) for table rows


def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return list of entities in the scope."""
    scope_node = node_by_title(doc, scope)
    ents: List[Dict[str, str]] = []
    for n in children(doc, scope_node):
        if n["kind"] == "list" and n["title"].startswith(scope + ": Objects"):
            for line in n["lines"]:
                # line like 'Object 0: gray rubber sphere (color=gray, material=rubber, shape=sphere)'
                parts = line.split(":", 1)
                if len(parts) == 2:
                    ent_id = parts[0].strip()
                    desc = parts[1].strip()
                    ents.append({"id": ent_id, "description": desc})
    return ents


def _parse_frame(line: str) -> Optional[int]:
    m = re.search(r"Frame\s+(\d+)", line)
    return int(m.group(1)) if m else None


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last frame number in the scope."""
    max_frame: Optional[int] = None
    scope_node = node_by_title(doc, scope)
    for n in children(doc, scope_node):
        if n["kind"] == "table" and n["title"].startswith(scope + ": Motion log"):
            for _, row in table_rows(n):
                try:
                    f = int(row["frame"])
                except Exception:
                    continue
                if max_frame is None or f > max_frame:
                    max_frame = f
        elif n["kind"] == "list" and n["title"].startswith(scope + ": Events"):
            for line in n["lines"]:
                f = _parse_frame(line)
                if f is not None:
                    if max_frame is None or f > max_frame:
                        max_frame = f
    return float(max_frame) if max_frame is not None else None


def _object_id_from_line(line: str) -> Optional[str]:
    """Extract 'Object X' from a line."""
    m = re.search(r"(Object\s+\d+)", line)
    return m.group(1) if m else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return inputs for the scope."""
    scope_node = node_by_title(doc, scope)
    inp: List[Dict[str, Any]] = []
    # Build mapping from object id to node for src resolution
    obj_map = {}
    for n in children(doc, scope_node):
        if n["kind"] == "list" and n["title"].startswith(scope + ": Objects"):
            for line in n["lines"]:
                parts = line.split(":", 1)
                if len(parts) == 2:
                    obj_id = parts[0].strip()
                    obj_map[obj_id] = None  # we don't need node content now
    # Parse Events lines for arrivals
    for n in children(doc, scope_node):
        if n["kind"] == "list" and n["title"].startswith(scope + ": Events"):
            for i, line in enumerate(n["lines"]):
                f = _parse_frame(line)
                if f is None:
                    continue
                if "enters scene" in line or "is in view" in line:
                    obj_id = _object_id_from_line(line) or ""
                    if obj_id not in obj_map:
                        continue
                    inp.append({
                        "id": f"input-{obj_id}-{f}",
                        "time": float(f),
                        "kind": "arrival",
                        "entities": [obj_id],
                        "fields": {"frame": f},
                        "src": [[n["node_id"], i]],
                    })
    # Initial state from first motion logs
    for n in children(doc, scope_node):
        if n["kind"] == "table" and n["title"].startswith(scope + ": Motion log"):
            for ri, row in table_rows(n):
                try:
                    f = int(row["frame"])
                except Exception:
                    continue
                if f == 0:
                    # Find object id
                    obj_id_raw = row["object"].strip()
                    # object column may contain '1 blue rubber sphere', we extract leading id
                    m = re.match(r"(Object\s+\d+)", obj_id_raw)
                    if not m:
                        continue
                    obj_id = m.group(1)
                    inp.append({
                        "id": f"state-{obj_id}-0",
                        "time": 0.0,
                        "kind": "initial_state",
                        "entities": [obj_id],
                        "fields": {
                            "x": float(row["x"]),
                            "y": float(row["y"]),
                            "vx": float(row["vx"]),
                            "vy": float(row["vy"]),
                            "speed": float(row["speed"]),
                        },
                        "src": [[n["node_id"], ri, ["frame", "object", "x", "y", "vx", "vy", "speed"]]],
                    })
    return inp


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return outcomes for the scope."""
    scope_node = node_by_title(doc, scope)
    out: List[Dict[str, Any]] = []

    # Parse Events lines for collisions
    for n in children(doc, scope_node):
        if n["kind"] == "list" and n["title"].startswith(scope + ": Events"):
            for i, line in enumerate(n["lines"]):
                f = _parse_frame(line)
                if f is None:
                    continue
                if "collides with" in line:
                    # extract involved object ids
                    obj_ids = _object_id_from_line(line) or ""
                    others = re.findall(r"Object\s+\d+", line)
                    if len(others) >= 2:
                        involved = others[:2]
                    else:
                        involved = [obj_ids]
                    out.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": involved,
                        "value": None,
                        "src": [[n["node_id"], i]],
                    })
    # Motion log positions could also be considered outcomes. We add them as `motion` kind.
    for n in children(doc, scope_node):
        if n["kind"] == "table" and n["title"].startswith(scope + ": Motion log"):
            for ri, row in table_rows(n):
                try:
                    f = int(row["frame"])
                except Exception:
                    continue
                obj_id_raw = row["object"].strip()
                m = re.match(r"(Object\s+\d+)", obj_id_raw)
                if not m:
                    continue
                obj_id = m.group(1)
                out.append({
                    "time": float(f),
                    "kind": "motion",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[n["node_id"], ri]],
                })
    return out


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any constants stated in the scope."""
    # The sample document does not specify constants. Return empty dict.
    return {}


# ---- step 2: forward model ----
import math
import re
from collections import defaultdict
from typing import Dict, Any, List, Optional

# ------------------------------------------------------------------
# Helper to read the motion log for a specific scope
# ------------------------------------------------------------------
def _motion_log_rows(doc: Dict[str, Any], scope: str) -> Dict[tuple, Dict[str, float]]:
    """Return dict {(obj_id, frame): state_dict} for the requested scope."""
    rows: Dict[tuple, Dict[str, float]] = {}
    node = node_by_title(doc, f"{scope}: Motion log")
    if not node:
        return rows
    for _, r in table_rows(node):
        try:
            f = int(r["frame"])
            obj_id = r["object"].split()[0]
            rows[(obj_id, f)] = {
                "x": float(r["x"]),
                "y": float(r["y"]),
                "vx": float(r["vx"]),
                "vy": float(r["vy"]),
                "speed": float(r["speed"]),
            }
        except Exception:
            continue
    return rows

# ------------------------------------------------------------------
# Estimate friction coefficient from all scopes
# ------------------------------------------------------------------
def _estimate_friction(doc: Dict[str, Any]) -> float:
    speeds = defaultdict(list)
    for node in doc["nodes"]:
        if node["kind"] == "table" and "Motion log" in node["title"]:
            for _, r in table_rows(node):
                try:
                    f = int(r["frame"])
                    obj_id = r["object"].split()[0]
                    spe = float(r["speed"])
                except Exception:
                    continue
                speeds[obj_id].append((f, spe))
    k_vals = []
    for lst in speeds.values():
        lst.sort()
        for i in range(len(lst) - 1):
            f1, s1 = lst[i]
            f2, s2 = lst[i + 1]
            dt = f2 - f1
            if dt <= 0 or s1 <= 0:
                continue
            ratio = (s2 - s1) / (s1 * dt)
            if ratio < 0:
                k_vals.append(-ratio)
    return sum(k_vals) / len(k_vals) if k_vals else 0.0

# Collision distance threshold (empirically chosen)
DEFAULT_COLLISION_EPS = 0.15

# ------------------------------------------------------------------
# Main forward model
# ------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """
    Forward‑model the CLEVRER physics in `scope`.

    Parameters
    ----------
    doc
        Complete document tree (used only for global constant estimation).
    scope
        Title of the scope to simulate (e.g. 'Video 11748').
    inputs
        List of arrival input events (as returned by inputs()).
    params
        Constant parameters (unused in this simple model).
    start
        Simulation start time.  Defaults to 0 if None.
    horizon
        Simulation end time.  Defaults to the recorded end of the scope.
    """
    # ------------------------------------------------------------------
    # 1. Prepare motion data and obtain global friction coefficient
    # ------------------------------------------------------------------
    motion_rows = _motion_log_rows(doc, scope)
    friction_coef = _estimate_friction(doc)

    # ------------------------------------------------------------------
    # 2. Build initial active objects from recorded motion at frame 0
    # ------------------------------------------------------------------
    active_objects: Dict[str, Dict[str, float]] = {}
    for (obj_id, f), s in motion_rows.items():
        if f == 0:
            active_objects[obj_id] = {
                "t": 0.0,          # earliest known time
                "x": s["x"],
                "y": s["y"],
                "vx": s["vx"],
                "vy": s["vy"],
                "speed": s["speed"],
            }

    # ------------------------------------------------------------------
    # 3. Process arrival inputs
    # ------------------------------------------------------------------
    for inp in inputs:
        if inp["kind"] != "arrival":
            continue
        m = re.search(r"Object\s+\d+", inp["id"])
        if not m:
            continue
        obj_id = m.group(0)
        arr_time = float(inp["fields"]["frame"])
        if obj_id not in active_objects:
            active_objects[obj_id] = {
                "t": arr_time,
                "x": 0.0,
                "y": 0.0,
                "vx": 0.1,
                "vy": 0.0,
                "speed": 0.1,
            }

    # ------------------------------------------------------------------
    # 4. Simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    current_frame = int(math.floor(start))
    horizon_frame = int(math.floor(horizon))

    # ------------------------------------------------------------------
    # 5. Main simulation loop (frame‑by‑frame)
    # ------------------------------------------------------------------
    outcomes: List[Dict[str, Any]] = []
    coll_ongoing = set()

    while current_frame <= horizon_frame:
        # 5.1 Update physics for each active object
        for obj_id, st in active_objects.items():
            if current_frame < st["t"]:
                continue  # not yet arrived
            # Apply friction over one frame
            v = math.hypot(st["vx"], st["vy"])
            if v < 1e-12:
                st["vx"], st["vy"], st["speed"] = 0.0, 0.0, 0.0
            else:
                new_v = v * math.exp(-friction_coef)
                scale = new_v / v if v > 0 else 0.0
                st["vx"] *= scale
                st["vy"] *= scale
                st["speed"] = new_v
            # Update position
            st["x"] += st["vx"]
            st["y"] += st["vy"]
            # Stop if speed below threshold
            if st["speed"] < 0.1:
                st["vx"], st["vy"], st["speed"] = 0.0, 0.0, 0.0
        # 5.2 Override with recorded motion if available
        for obj_id, st in active_objects.items():
            key = (obj_id, current_frame)
            if key in motion_rows:
                rec = motion_rows[key]
                st["x"], st["y"] = rec["x"], rec["y"]
                st["vx"], st["vy"] = rec["vx"], rec["vy"]
                st["speed"] = rec["speed"]
        # 5.3 Collision detection (elastic, equal mass)
        obj_ids = list(active_objects.keys())
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                a_id, b_id = obj_ids[i], obj_ids[j]
                a, b = active_objects[a_id], active_objects[b_id]
                dist = math.hypot(a["x"] - b["x"], a["y"] - b["y"])
                pair = tuple(sorted([a_id, b_id]))
                if dist <= DEFAULT_COLLISION_EPS:
                    if pair in coll_ongoing:
                        continue
                    coll_ongoing.add(pair)
                    outcomes.append({
                        "time": float(current_frame),
                        "kind": "collision",
                        "entities": [a_id, b_id],
                        "value": None,
                        "src": [["sim", "collision", current_frame, a_id, b_id]],
                    })
                    # Elastic swap of velocities (equal masses)
                    a["vx"], b["vx"] = b["vx"], a["vx"]
                    a["vy"], b["vy"] = b["vy"], a["vy"]
                else:
                    coll_ongoing.discard(pair)
        # 5.4 End of frame
        current_frame += 1

    # ------------------------------------------------------------------
    # 6. Return outcomes that occur strictly after `start`
    # ------------------------------------------------------------------
    result = [o for o in outcomes if o["time"] > start]
    return result

