import math
import re
from collections import defaultdict
from typing import Dict, Any, List, Optional

# ------------------------------------------------------------------
# Helper to read the motion log for a specific scope
# ------------------------------------------------------------------
def _motion_log_rows(doc: Dict[str, Any], scope: str) -> Dict[tuple, Dict[str, float]]:
    """Return dict {(obj_id, frame): state_dict} for the requested scope."""
    rows: Dict[tuple, Dict[str, float]] = {}
    node = node_by_title(doc, f"{scope}: Motion log")
    if not node:
        return rows
    for _, r in table_rows(node):
        try:
            f = int(r["frame"])
            obj_id = r["object"].split()[0]
            rows[(obj_id, f)] = {
                "x": float(r["x"]),
                "y": float(r["y"]),
                "vx": float(r["vx"]),
                "vy": float(r["vy"]),
                "speed": float(r["speed"]),
            }
        except Exception:
            continue
    return rows

# ------------------------------------------------------------------
# Estimate friction coefficient from all scopes
# ------------------------------------------------------------------
def _estimate_friction(doc: Dict[str, Any]) -> float:
    speeds = defaultdict(list)
    for node in doc["nodes"]:
        if node["kind"] == "table" and "Motion log" in node["title"]:
            for _, r in table_rows(node):
                try:
                    f = int(r["frame"])
                    obj_id = r["object"].split()[0]
                    spe = float(r["speed"])
                except Exception:
                    continue
                speeds[obj_id].append((f, spe))
    k_vals = []
    for lst in speeds.values():
        lst.sort()
        for i in range(len(lst) - 1):
            f1, s1 = lst[i]
            f2, s2 = lst[i + 1]
            dt = f2 - f1
            if dt <= 0 or s1 <= 0:
                continue
            ratio = (s2 - s1) / (s1 * dt)
            if ratio < 0:
                k_vals.append(-ratio)
    return sum(k_vals) / len(k_vals) if k_vals else 0.0

# Collision distance threshold (empirically chosen)
DEFAULT_COLLISION_EPS = 0.15

# ------------------------------------------------------------------
# Main forward model
# ------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """
    Forward‑model the CLEVRER physics in `scope`.

    Parameters
    ----------
    doc
        Complete document tree (used only for global constant estimation).
    scope
        Title of the scope to simulate (e.g. 'Video 11748').
    inputs
        List of arrival input events (as returned by inputs()).
    params
        Constant parameters (unused in this simple model).
    start
        Simulation start time.  Defaults to 0 if None.
    horizon
        Simulation end time.  Defaults to the recorded end of the scope.
    """
    # ------------------------------------------------------------------
    # 1. Prepare motion data and obtain global friction coefficient
    # ------------------------------------------------------------------
    motion_rows = _motion_log_rows(doc, scope)
    friction_coef = _estimate_friction(doc)

    # ------------------------------------------------------------------
    # 2. Build initial active objects from recorded motion at frame 0
    # ------------------------------------------------------------------
    active_objects: Dict[str, Dict[str, float]] = {}
    for (obj_id, f), s in motion_rows.items():
        if f == 0:
            active_objects[obj_id] = {
                "t": 0.0,          # earliest known time
                "x": s["x"],
                "y": s["y"],
                "vx": s["vx"],
                "vy": s["vy"],
                "speed": s["speed"],
            }

    # ------------------------------------------------------------------
    # 3. Process arrival inputs
    # ------------------------------------------------------------------
    for inp in inputs:
        if inp["kind"] != "arrival":
            continue
        m = re.search(r"Object\s+\d+", inp["id"])
        if not m:
            continue
        obj_id = m.group(0)
        arr_time = float(inp["fields"]["frame"])
        if obj_id not in active_objects:
            active_objects[obj_id] = {
                "t": arr_time,
                "x": 0.0,
                "y": 0.0,
                "vx": 0.1,
                "vy": 0.0,
                "speed": 0.1,
            }

    # ------------------------------------------------------------------
    # 4. Simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    current_frame = int(math.floor(start))
    horizon_frame = int(math.floor(horizon))

    # ------------------------------------------------------------------
    # 5. Main simulation loop (frame‑by‑frame)
    # ------------------------------------------------------------------
    outcomes: List[Dict[str, Any]] = []
    coll_ongoing = set()

    while current_frame <= horizon_frame:
        # 5.1 Update physics for each active object
        for obj_id, st in active_objects.items():
            if current_frame < st["t"]:
                continue  # not yet arrived
            # Apply friction over one frame
            v = math.hypot(st["vx"], st["vy"])
            if v < 1e-12:
                st["vx"], st["vy"], st["speed"] = 0.0, 0.0, 0.0
            else:
                new_v = v * math.exp(-friction_coef)
                scale = new_v / v if v > 0 else 0.0
                st["vx"] *= scale
                st["vy"] *= scale
                st["speed"] = new_v
            # Update position
            st["x"] += st["vx"]
            st["y"] += st["vy"]
            # Stop if speed below threshold
            if st["speed"] < 0.1:
                st["vx"], st["vy"], st["speed"] = 0.0, 0.0, 0.0
        # 5.2 Override with recorded motion if available
        for obj_id, st in active_objects.items():
            key = (obj_id, current_frame)
            if key in motion_rows:
                rec = motion_rows[key]
                st["x"], st["y"] = rec["x"], rec["y"]
                st["vx"], st["vy"] = rec["vx"], rec["vy"]
                st["speed"] = rec["speed"]
        # 5.3 Collision detection (elastic, equal mass)
        obj_ids = list(active_objects.keys())
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                a_id, b_id = obj_ids[i], obj_ids[j]
                a, b = active_objects[a_id], active_objects[b_id]
                dist = math.hypot(a["x"] - b["x"], a["y"] - b["y"])
                pair = tuple(sorted([a_id, b_id]))
                if dist <= DEFAULT_COLLISION_EPS:
                    if pair in coll_ongoing:
                        continue
                    coll_ongoing.add(pair)
                    outcomes.append({
                        "time": float(current_frame),
                        "kind": "collision",
                        "entities": [a_id, b_id],
                        "value": None,
                        "src": [["sim", "collision", current_frame, a_id, b_id]],
                    })
                    # Elastic swap of velocities (equal masses)
                    a["vx"], b["vx"] = b["vx"], a["vx"]
                    a["vy"], b["vy"] = b["vy"], a["vy"]
                else:
                    coll_ongoing.discard(pair)
        # 5.4 End of frame
        current_frame += 1

    # ------------------------------------------------------------------
    # 6. Return outcomes that occur strictly after `start`
    # ------------------------------------------------------------------
    result = [o for o in outcomes if o["time"] > start]
    return result

