            rows[(obj_id, f)] = {
                "x": float(r["x"]),
                "y": float(r["y"]),
                "vx": float(r["vx"]),
                "vy": float(r["vy"]),
                "speed": float(r["speed"]),
            }
        except Exception:
            continue
    return rows


# ------------------------------------------------------------------
# Constants estimated from the whole dataset
# ------------------------------------------------------------------
def _estimate_friction(doc: Dict[str, Any]) -> float:
    speeds = defaultdict(list)
    for node in doc["nodes"]:
        if node["kind"] == "table" and "Motion log" in node["title"]:
            for _, r in table_rows(node):
                try:
                    f = int(r["frame"])
                    obj_id = r["object"].split()[0]
                    spe = float(r["speed"])
                except Exception:
                    continue
                speeds[obj_id].append((f, spe))
    k_vals = []
    for lst in speeds.values():
        lst.sort()
        for i in range(len(lst) - 1):
            f1, s1 = lst[i]
            f2, s2 = lst[i + 1]
            dt = f2 - f1
            if dt <= 0 or s1 <= 0:
                continue
            ratio = (s2 - s1) / (s1 * dt)
            if ratio < 0:
                k_vals.append(-ratio)
    return sum(k_vals) / len(k_vals) if k_vals else 0.0


# Global friction coefficient (unused in the simplified model, kept for completeness)
GLOBAL_FRICTION_COEF = _estimate_friction(doc)

# Empirical collision distance threshold
COLLISION_EPS = 0.2


# ------------------------------------------------------------------
# Forward model
# ------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """
    Replay the CLEVRER scene in `scope` from `start` to `horizon`.

    The simulation is built around the recorded motion logs that remain after the
    hidden‑cell step.  For frames that are absent we forward‑propagate the last
    known position and velocity; collisions are detected when objects come
    within ``COLLISION_EPS``.  Velocities are simply carried forward – no
    friction or other forces are applied in this minimal model, because the
    recorded data already captures the effects of friction.  The model uses
    the `inputs` only to determine which objects are present in the scene.
    """
    # ------------------------------------------------------------------
    # 1. Gather remaining motion data for this scope
    # ------------------------------------------------------------------
    motion_rows = _motion_log_rows(doc, scope)

    # ------------------------------------------------------------------
    # 2. Determine active objects from inputs (arrival events)
    # ------------------------------------------------------------------
    active_objs = set()
    for inp in inputs:
        if inp["kind"] == "arrival":
            m = re.search(r"Object\s+\d+", inp["id"])
            if m:
                active_objs.add(m.group(0))

    # ------------------------------------------------------------------
    # 3. Initialise a state dictionary for each active object.
    #    Use the latest recorded frame ≤ start (or at start) to get position
    #    and velocity.  If none, default to zero.
    # ------------------------------------------------------------------
    state: Dict[str, Dict[str, float]] = {}
    for obj in active_objs:
        # find last frame <= start
        latest_f = -1
        latest_vec = None
        for (o, f), rec in motion_rows.items():
            if o != obj:
                continue
            if f <= (start or 0):
                if f > latest_f:
                    latest_f = f
                    latest_vec = rec
        if latest_vec:
            state[obj] = {
                "x": latest_vec["x"],
                "y": latest_vec["y"],
                "vx": latest_vec["vx"],
                "vy": latest_vec["vy"],
                "speed": latest_vec["speed"],
                "t": latest_f,
            }
        else:
            # no recorded data before start → default to origin
            state[obj] = {"x": 0.0, "y": 0.0, "vx": 0.1, "vy": 0.0, "speed": 0.1, "t": 0.0}

    # ------------------------------------------------------------------
    # 4. Simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    cur_frame = int(math.floor(start))
    end_frame = int(math.floor(horizon))

    # ------------------------------------------------------------------
    # 5. Main simulation loop
    # ------------------------------------------------------------------
    outcomes: List[Dict[str, Any]] = []
    coll_ongoing: set = set()

    while cur_frame <= end_frame:
        # 5.1 Advance physics: positions = pos + velocity
        for obj_id, s in state.items():
            # Skip objects that have not appeared yet
            if cur_frame < s["t"]:
                continue
            s["x"] += s["vx"]
            s["y"] += s["vy"]

        # 5.2 Override with any recorded motion that exists for this frame
        for obj_id, s in state.items():
            key = (obj_id, cur_frame)
            if key in motion_rows:
                rec = motion_rows[key]
                s["x"], s["y"] = rec["x"], rec["y"]
                s["vx"], s["vy"] = rec["vx"], rec["vy"]
                s["speed"] = rec["speed"]

        # 5.3 Collision detection
        objs = list(state.keys())
        for i in range(len(objs)):
            for j in range(i + 1, len(objs)):
                a_id, b_id = objs[i], objs[j]
                a, b = state[a_id], state[b_id]
                dist = math.hypot(a["x"] - b["x"], a["y"] - b["y"])
                pair = tuple(sorted([a_id, b_id]))
                if dist <= COLLISION_EPS:
                    if pair in coll_ongoing:
                        continue
                    coll_ongoing.add(pair)
                    outcomes.append({
                        "time": float(cur_frame),
                        "kind": "collision",
                        "entities": [a_id, b_id],
                        "value": None,
                        "src": [["sim", "collision", cur_frame, a_id, b_id]],
                    })
                    # Elastic interaction: swap velocities (equal masses)
                    a["vx"], b["vx"] = b["vx"], a["vx"]
                    a["vy"], b["vy"] = b["vy"], a["vy"]
                else:
                    coll_ongoing.discard(pair)

        cur_frame += 1

    # Return outcomes that occur after the requested start time
    return [o for o in outcomes if o["time"] > start]

