        # 5.1 Advance positions (no physics except backward propagation)
        for obj_id, s in state.items():
            if cur_frame < s["t"]:
                continue
            s["x"] += s["vx"]
            s["y"] += s["vy"]

        # 5.2 Override with any surviving recorded motion for this frame
        for obj_id, s in state.items():
            key = (obj_id, cur_frame)
