                rec = motion_rows[key]
                s["x"], s["y"] = rec["x"], rec["y"]
                s["vx"], s["vy"] = rec["vx"], rec["vy"]
                s["speed"] = rec["speed"]

        # 5.3 Detect collisions (elastic interaction: swap velocities)
        objects = list(state.keys())
        for i in range(len(objects)):
            for j in range(i + 1, len(objects)):
                a_id, b_id = objects[i], objects[j]
                a, b = state[a_id], state[b_id]
                dist = math.hypot(a["x"] - b["x"], a["y"] - b["y"])
                pair = tuple(sorted([a_id, b_id]))
                if dist <= _COLLISION_EPS:
                    if pair in coll_ongoing:
                        continue
                    coll_ongoing.add(pair)
