                    a["vx"], b["vx"] = b["vx"], a["vx"]
                    a["vy"], b["vy"] = b["vy"], a["vy"]
                else:
                    coll_ongoing.discard(pair)

        cur_frame += 1

    # 6. Return outcomes that occur strictly after `start`
    return [o for o in outcomes if o["time"] > start]

