                "x": latest_rec["x"],
                "y": latest_rec["y"],
                "vx": latest_rec["vx"],
                "vy": latest_rec["vy"],
                "speed": latest_rec["speed"],
                "t": latest_f,
            }
        else:
            # No prior record – assume origin with a small default velocity
            state[obj] = {"x": 0.0, "y": 0.0, "vx": 0.1, "vy": 0.0, "speed": 0.1, "t": 0.0}

