    coll_ongoing: set = set()

    while cur_frame <= end_frame:
        # 5.1 advance positions with current velocities
        for obj_id, s in state.items():
            if cur_frame < s["t"]:
                continue
            s["x"] += s["vx"]
            s["y"] += s["vy"]

        # 5.2 override with any surviving recorded data for this frame
        for obj_id, s in state.items():
            key = (obj_id, cur_frame)
            if key in motion_rows:
                rec = motion_rows[key]
                s["x"], s["y"] = rec["x"], rec["y"]
                s["vx"], s["vy"] = rec["vx"], rec["vy"]
                s["speed"] = rec["speed"]

        # 5.3 detect collisions
        objects = list(state.keys())
        for i in range(len(objects)):
            for j in range(i + 1, len(objects)):
                a_id, b_id = objects[i], objects[j]
                a, b = state[a_id], state[b_id]
                dist = math.hypot(a["x"] - b["x"], a["y"] - b["y"])
                pair = tuple(sorted([a_id, b_id]))
                if dist <= _COLLISION_EPS:
                    if pair in coll_ongoing:
                        continue
                    coll_ongoing.add(pair)
                    outcomes.append({
                        "time": float(cur_frame),
                        "kind": "collision",
                        "entities": [a_id, b_id],
                        "value": None,
                        "src": [["sim", "collision", cur_frame, a_id, b_id]],
                    })
                    # Elastic swap of velocities (equal masses)
                    a["vx"], b["vx"] = b["vx"], a["vx"]
                    a["vy"], b["vy"] = b["vy"], a["vy"]
                else:
                    coll_ongoing.discard(pair)

        cur_frame += 1

    # 6. Return outcomes that occur after the requested start time
    return [o for o in outcomes if o["time"] > start]

