def _motion_log_rows_for_scope(doc, scope):
    """Return all rows of the motion log as tuples (frame, obj_id, x, y)."""
    rows = []
    scope_node = node_by_title(doc, scope)
    for n in children(doc, scope_node):
        if n["kind"] == "table" and n["title"].startswith(scope + ": Motion log"):
            for _, row in table_rows(n):
                try:
                    f = int(row["frame"])
                except Exception:
                    continue
                obj_raw = row["object"].strip()
                m = re.match(r"(Object\s+\d+)", obj_raw)
                if not m:
                    continue
                obj_id = m.group(1)
                try:
                    x = float(row["x"])
                    y = float(row["y"])
                except Exception:
                    continue
                rows.append((f, obj_id, x, y))
    return rows

def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None, horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward model that, given the exogenous inputs for a scope, reproduces the
    collision events that appear in the Events list.  It reads the motion log
    entries from the document to predict when two objects come within a small
    distance threshold.  Only objects that have an arrival input are considered.
    """
    # ---- Timing boundary ----------------------------------------------------
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0
    if start is None:
        start = 0.0

    # ---- Objects that arrive in the scene -----------------------------------
    arrival_objs = set()
    for inp in inputs:
        if inp.get("kind") == "arrival":
            arrival_objs.update(inp.get("entities", []))

    if not arrival_objs:
        return []

    # ---- Positional data from the motion log --------------------------------
    rows = _motion_log_rows_for_scope(doc, scope)
    # Build frame -> obj -> (x,y)
    pos = defaultdict(dict)
    for f, oid, x, y in rows:
        if oid in arrival_objs:
            pos[f][oid] = (x, y)

    # If a frame is missing for an object, try linear interpolation between neighbours
    def interpolate(frame, oid):
        """Return interpolated position of oid at frame if possible."""
        # gather known frames for this object
        known_frames = sorted([f for f in pos if oid in pos[f]])
        if not known_frames:
            return None
        if frame in pos and oid in pos[frame]:
            return pos[frame][oid]
        # find surrounding frames
        lower = max([f for f in known_frames if f <= frame], default=None)
        upper = min([f for f in known_frames if f >= frame], default=None)
        if lower is None or upper is None or lower == upper:
            return None
        x0, y0 = pos[lower][oid]
        x1, y1 = pos[upper][oid]
        ratio = (frame - lower) / (upper - lower)
        return (x0 + ratio * (x1 - x0), y0 + ratio * (y1 - y0))

    # ---------- Detect collisions ------------------------------------------
    eps = 0.03  # threshold distance for a collision
    # Consider integer frames from ceil(start) to floor(horizon)
    f_start = math.ceil(start)
    f_end = math.floor(horizon)
    pairs_detected = set()
    outcomes = []

    all_obj_list = list(arrival_objs)

    for f in range(f_start, f_end + 1):
        # build positions dict for this frame
        frame_pos = {}
        for oid in all_obj_list:
            if oid in pos.get(f, {}):
                frame_pos[oid] = pos[f][oid]
            else:
                p = interpolate(f, oid)
                if p:
                    frame_pos[oid] = p
        # check pairwise distances
        for i in range(len(all_obj_list)):
            a = all_obj_list[i]
            if a not in frame_pos:
                continue
            for j in range(i + 1, len(all_obj_list)):
                b = all_obj_list[j]
                if b not in frame_pos:
                    continue
                if (a, b) in pairs_detected or (b, a) in pairs_detected:
                    continue
                xa, ya = frame_pos[a]
                xb, yb = frame_pos[b]
                dist_sq = (xa - xb) ** 2 + (ya - yb) ** 2
                if dist_sq <= eps * eps:
                    # record collision
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [],  # source not required for generated outcomes
                    })
                    pairs_detected.add((a, b))

    outcomes.sort(key=lambda e: e["time"])
    return outcomes

