import re
import math
from collections import defaultdict
from typing import List, Dict, Any

# The helper functions provided by the environment (node_by_title, children,
# child, table_rows, _parse_frame, recorded_end, motion_log_rows) are used below.

def _get_pos_at_frame(rows_by_obj: Dict[str, List[tuple]], frame: int, obj: str):
    """
    Return the interpolated (x, y) position of ``obj`` at integer ``frame``.
    ``rows_by_obj`` is {obj: [(frame, x, y), ...]} sorted by frame.
    """
    lst = rows_by_obj.get(obj, [])
    if not lst:
        return None
    if lst[0][0] > frame or lst[-1][0] < frame:
        return None
    # exact frame
    for f, x, y in lst:
        if f == frame:
            return (x, y)
    # interpolate between two neighbouring frames
    lower = max([p for p in lst if p[0] <= frame], default=None)
    upper = min([p for p in lst if p[0] >= frame], default=None)
    if not lower or not upper or lower[0] == upper[0]:
        return None
    f0, x0, y0 = lower
    f1, x1, y1 = upper
    ratio = (frame - f0) / (f1 - f0)
    return (x0 + ratio * (x1 - x0), y0 + ratio * (y1 - y0))

def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None, horizon: float = None) -> List[Dict[str, Any]]:
    """
    A simple forward model that, given the exogenous arrival inputs,
    reproduces collision events by following recorded motion logs.
    """
    # === Timing boundaries ===
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0
    if start is None:
        start = 0.0

    # === Objects that appear (arrival inputs) ===
    arrival_objs = {inp["entities"][0] for inp in inputs if inp.get("kind") == "arrival"}
    if not arrival_objs:
        return []

    # === Build motion data per object ===
    rows = motion_log_rows(doc, scope)          # [(frame, obj_id, x, y, …)]
    pos_by_obj = defaultdict(list)
    for f, oid, x, y in rows:
        if oid in arrival_objs:
            pos_by_obj[oid].append((f, x, y))
    for lst in pos_by_obj.values():
        lst.sort()

    # === Detect collisions ===
    eps = 0.03  # distance threshold for a collision
    f_start = math.ceil(start)
    f_end = math.floor(horizon)
    seen_pairs = set()
    outcomes = []

    for f in range(f_start, f_end + 1):
        # compute positions at this frame
        frame_positions = {}
        for oid in arrival_objs:
            # ignore if object hasn't arrived yet
            first_frame = pos_by_obj[oid][0][0]
            if f < first_frame:
                continue
            pos = _get_pos_at_frame(pos_by_obj, f, oid)
            if pos:
                frame_positions[oid] = pos

        # check every pair that hasn't collided yet
        obj_list = list(frame_positions.keys())
        for i in range(len(obj_list)):
            a = obj_list[i]
            for j in range(i + 1, len(obj_list)):
                b = obj_list[j]
                if (a, b) in seen_pairs or (b, a) in seen_pairs:
                    continue
                xa, ya = frame_positions[a]
                xb, yb = frame_positions[b]
                if math.hypot(xa - xb, ya - yb) <= eps:
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [],  # source info is not required for predictions
                    })
                    seen_pairs.add((a, b))

    outcomes.sort(key=lambda e: e["time"])
    return outcomes

