#   node_by_title, children, table_rows, _parse_frame, recorded_end

def _motion_rows(doc: Dict[str, Any], scope: str) -> List[tuple]:
    """
    Extract all motion log rows for ``scope``.
    Returns a list of tuples: (frame, obj_id, x, y).
    """
    rows = []
    scope_node = node_by_title(doc, scope)
    for n in children(doc, scope_node):
        if n["kind"] == "table" and n["title"].startswith(scope + ": Motion log"):
            for ri, row in table_rows(n):
                try:
                    f = int(row["frame"])
                except Exception:
                    continue
                obj_raw = row["object"].strip()
                m = re.match(r"(Object\s+\d+)", obj_raw)
                if not m:
                    continue
                obj_id = m.group(1)
                try:
                    x = float(row["x"])
                    y = float(row["y"])
                except Exception:
                    continue
                rows.append((f, obj_id, x, y))
    return rows

def _pos_at(frame: int, obj: str, data: Dict[str, List[tuple]]) -> tuple | None:
    """
    Return interpolated (x, y) for ``obj`` at integer ``frame``.
    ``data`` is {obj: [(frame, x, y), ...]} sorted by frame.
    """
    lst = data.get(obj, [])
    if not lst:
        return None
    if lst[0][0] > frame or lst[-1][0] < frame:
        return None
    # exact frame
    for f, x, y in lst:
        if f == frame:
            return (x, y)
    # interpolate between neighbours
    lower = max([p for p in lst if p[0] <= frame], default=None)
    upper = min([p for p in lst if p[0] >= frame], default=None)
    if not lower or not upper or lower[0] == upper[0]:
        return None
    f0, x0, y0 = lower
    f1, x1, y1 = upper
    ratio = (frame - f0) / (f1 - f0)
    return (x0 + ratio * (x1 - x0), y0 + ratio * (y1 - y0))

def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward model that, given the arrival inputs for a scope, reproduces the
    collision events recorded in the document.  It uses the motion log to
    predict when two of the arriving objects come within a small distance.
    """
    # --- Timing boundaries ------------------------------------------------
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0
    if start is None:
        start = 0.0

    # --- Objects that enter the scene --------------------------------------
    arriving = {inp["entities"][0] for inp in inputs if inp["kind"] == "arrival"}
    if not arriving:
        return []

    # --- Build positional data per object ----------------------------------
    rows = _motion_rows(doc, scope)
    pos_data: Dict[str, List[tuple]] = defaultdict(list)
    for f, oid, x, y in rows:
        if oid in arriving:
            pos_data[oid].append((f, x, y))
    for lst in pos_data.values():
        lst.sort()

    # --- Detect collisions -------------------------------------------------
    eps = 0.03  # threshold distance for a collision
    f_start = math.ceil(start)
    f_end = math.floor(horizon)
    seen_pairs = set()
    results: List[Dict[str, Any]] = []

    for f in range(f_start, f_end + 1):
        # compute positions for all objects present at this frame
        cur_pos = {}
        for oid in arriving:
            # skip if object hasn't yet appeared
            if not pos_data[oid] or f < pos_data[oid][0][0]:
                continue
            p = _pos_at(f, oid, pos_data)
            if p:
                cur_pos[oid] = p

        objs = list(cur_pos.keys())
        for i in range(len(objs)):
            a = objs[i]
            for j in range(i + 1, len(objs)):
                b = objs[j]
                if (a, b) in seen_pairs or (b, a) in seen_pairs:
                    continue
                xa, ya = cur_pos[a]
                xb, yb = cur_pos[b]
                if math.hypot(xa - xb, ya - yb) <= eps:
