                        "time": float(f),
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [],  # prediction, no source link
                    })
                    seen_pairs.add((a, b))

    results.sort(key=lambda e: e["time"])
    return results

