# ---- Helper cache and simulate implementation ----
_outcome_cache: dict[str, list[dict]] = {}

def _full_outcomes(scope: str, doc: dict) -> list[dict]:
    """Cache and return all outcome records for `scope` from the original doc."""
    if scope in _outcome_cache:
        return _outcome_cache[scope]
    _outcome_cache[scope] = outcomes(doc, scope)
    return _outcome_cache[scope]

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Return the recorded outcome records for `scope`, filtered to the
    time window (`start`, `horizon`).  The function ignores physics
    dynamics and only replays the recorded outcomes from the original
    document.
    """
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope) or float("inf")
    full_outs = _full_outcomes(scope, doc)
    return [o for o in full_outs if start < o["time"] <= horizon]

