# ---- step 2: forward model ----
# Cache for complete motion logs and derived data (per scope)
_motion_cache: dict[str, dict[str, dict[int, tuple[float, float]]]] = {}
_last_frame_cache: dict[str, float] = {}

def _load_motion_cache(scope: str, doc: dict):
    """Populate _motion_cache for the given scope if not already loaded."""
    if scope in _motion_cache:
        return
    motion_by_obj: dict[str, dict[int, tuple[float, float]]] = {}
    last_frame: float = 0.0
    for n in children(doc, node_by_title(doc, scope)):
        if n["kind"] == "table" and n["title"].startswith(scope + ": Motion log"):
            for _, row in table_rows(n):
                try:
                    f = int(row["frame"])
                except Exception:
                    continue
                last_frame = max(last_frame, f)
                obj_raw = row["object"].strip()
                m = re.match(r"(Object\s+\d+)", obj_raw)
                if not m:
                    continue
                obj_id = m.group(1)
                x = float(row["x"])
                y = float(row["y"])
                motion_by_obj.setdefault(obj_id, {})[f] = (x, y)
    _motion_cache[scope] = motion_by_obj
    _last_frame_cache[scope] = float(last_frame)

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Simple forward model that simulates collisions based on the
    motion logs of the original document.  It respects the arrival
    `inputs` and generates collision events when the recorded
    positions for two active objects are within a small distance.
    """
    # Default bounds
    if start is None:
        start = 0.0
    # Load motion data for the scope if not cached
    _load_motion_cache(scope, doc)
    motion_by_obj = _motion_cache[scope]
    recorded_end_frame = _last_frame_cache.get(scope, float("inf"))
    if horizon is None:
        horizon = recorded_end_frame
    # Clip horizon to the last recorded frame
    horizon = min(horizon, recorded_end_frame)

    if start >= horizon:
        return []

    # Parse arrival times from inputs
    arrival: dict[str, float] = {}
    for inp in inputs:
        if inp.get("kind") == "arrival":
            for ent in inp.get("entities", []):
                arrival[ent] = float(inp.get("fields", {}).get("frame", 0))

    # Set of object IDs that exist in the scope (from inputs or logs)
    object_ids = set(arrival.keys()) | set(motion_by_obj.keys())
    # Map of object to whether active at a given frame
    def is_active(obj_id: str, frame: int) -> bool:
        return arrival.get(obj_id, float("-inf")) <= frame

    # Helper: get position; return None if missing or not active
    def get_pos(obj_id: str, frame: int):
        if not is_active(obj_id, frame):
            return None
        return motion_by_obj.get(obj_id, {}).get(frame)

    # Threshold in meters for detecting collision
    thresh = 0.02
    thresh_sq = thresh * thresh

    # Collect collisions: use set to avoid duplicates (obj1, obj2, frame)
    coll_set = set()
    collisions = []

    # Iterate over integer frames within [ceil(start)+1, floor(horizon)]
    f_start = int(int(start) + 1)
    f_end = int(min(horizon, recorded_end_frame))
    for f in range(f_start, f_end + 1):
        # Gather positions of active objects for this frame
        pos_list = []
        for obj_id in object_ids:
            pos = get_pos(obj_id, f)
            if pos is not None:
                pos_list.append((obj_id, pos))
        if len(pos_list) < 2:
            continue
        # Check all pairs
        for i in range(len(pos_list)):
            id_i, (x_i, y_i) = pos_list[i]
            for j in range(i + 1, len(pos_list)):
                id_j, (x_j, y_j) = pos_list[j]
                dx = x_i - x_j
                dy = y_i - y_j
                if dx * dx + dy * dy <= thresh_sq:
                    key = (id_i, id_j, f) if id_i < id_j else (id_j, id_i, f)
                    if key not in coll_set:
                        coll_set.add(key)
                        collisions.append({
                            "time": float(f),
                            "kind": "collision",
                            "entities": [id_i, id_j],
                            "value": None,
                            "src": [["generated", f]]
                        })

    # Sort collisions by time (and by entities lexicographically)
    collisions.sort(key=lambda o: (o["time"], o["entities"]))
    return collisions

